import {resolveStyleState} from './resolver-v1.js';
import {normalizePersonality,normalizeWardrobe} from './assisted-creation.js';
import {commitCharacter,migrateCharacterState} from './character-library.js';
import {migrateProjectState} from './project-library.js';
import {createDefaultInspirationState,normalizeInspirationState} from './inspiration.js';
import {migrateTakeSemantics,withTakeSemantics} from './take-semantics.js';

const clone=value=>structuredClone(value);
export const STAGE_MODES=Object.freeze(['empty','core-ready','reference','take']);
export const blankState=()=>({character:null,characters:[],activeCharacterId:null,projects:[],activeProjectId:null,inspirationState:createDefaultInspirationState(),styleMix:{influences:[],strength:.8,locks:{}},interestState:{characterInterests:[],activeContext:[]},scene:null,wardrobe:normalizeWardrobe({source:'resolved',items:[],locked:false}),manualOverrides:{},resolverLocks:{},visualSettings:{expression:{pose:'Relaxed stance',expression:'Soft neutral'},photography:{shotType:'Candid',lens:'50mm',angle:'Eye level',locked:false},lighting:{behaviour:'Natural',colourTreatment:'Warm'}},generationOptions:{seed:'promptforge-1',keepCharacter:true,keepStyleMix:false,keepScene:false,newPose:true,newWardrobe:true},selectedTake:null,takes:[],compiledPrompts:[],dirty:false});

export function stageMode(state){if(!state.character)return 'empty';if(state.selectedTake&&state.takes.some(t=>t.id===state.selectedTake))return 'take';if(state.character.references?.length)return 'reference';return 'core-ready'}
export function createCharacter(state,input){const existing=state.character;const character={id:existing?.id||input.id||`character_${Date.now()}_${Math.random().toString(36).slice(2,8)}`,name:input.name||existing?.name||'New Character',identity:{age:Number(input.age)||existing?.identity?.age||24,location:input.location||existing?.identity?.location||'Choose a location',occupation:input.occupation||existing?.identity?.occupation||'Choose an occupation'},appearance:existing?.appearance||{facialStructure:['soft oval'],facialFeatures:['brown almond eyes'],skinDetails:['natural complexion'],hair:{colour:'dark brown',style:'messy bun'},signatureFeatures:['silver necklace']},personality:normalizePersonality(existing?.personality),interests:existing?.interests||['programming','photography'],references:existing?.references||[],locks:existing?.locks||{identity:true,appearance:true},revision:(existing?.revision||0)+1};return {...commitCharacter(state,character),interestState:{...state.interestState,characterInterests:[...character.interests]},dirty:false}}
export function editCharacter(state,changes){if(!state.character)return state;const next=createCharacter(state,{...state.character.identity,...changes,name:changes.name||state.character.name});return {...next,dirty:true}}
export function addReference(state,reference={source:'mock-local'}){if(!state.character)throw new Error('Character Core required before adding a reference');const updated={...state.character,references:[...(state.character.references||[]),{id:`ref_${Date.now()}`,createdAt:new Date().toISOString(),...reference}]};return {...commitCharacter(state,updated),selectedTake:null,dirty:false}}
export const serializeState=state=>JSON.stringify(state);
export const restoreState=serialized=>{const defaults=blankState(),saved=JSON.parse(serialized),migrated=migrateProjectState(migrateCharacterState({...defaults,...saved})),character=migrated.character?{...migrated.character,personality:normalizePersonality(migrated.character.personality)}:null;return {...migrated,character,characters:migrated.characters.map(item=>item.id===character?.id?character:item),inspirationState:normalizeInspirationState(saved.inspirationState),styleMix:{...defaults.styleMix,...saved.styleMix},interestState:{...defaults.interestState,...saved.interestState,characterInterests:saved.interestState?.characterInterests||character?.interests||[]},wardrobe:normalizeWardrobe({...defaults.wardrobe,...saved.wardrobe}),visualSettings:{expression:{...defaults.visualSettings.expression,...saved.visualSettings?.expression},photography:{...defaults.visualSettings.photography,...saved.visualSettings?.photography},lighting:{...defaults.visualSettings.lighting,...saved.visualSettings?.lighting}},generationOptions:{...defaults.generationOptions,...saved.generationOptions},takes:Array.isArray(saved.takes)?migrateTakeSemantics(migrated.takes):[],compiledPrompts:Array.isArray(saved.compiledPrompts)?migrated.compiledPrompts:[]}};
export function resolveStudioState(state,options={}){if(!state.character)throw new Error('Character Core required before compilation');return resolveStyleState(state,options.seed??state.generationOptions?.seed??'promptforge-1',options.registry||state.contentCatalogue)}
const promptList=value=>Array.isArray(value)?value.filter(Boolean).join(', '):value||'';
export const MockCompiler=Object.freeze({compile(resolved){const c=resolved.character,context=resolved.context||{},appearance=c.appearance||{},photo=context.visualSettings?.photography||{},lighting=context.visualSettings?.lighting||{},expression=context.visualSettings?.expression||{},wardrobe=context.wardrobe||{},scene=context.scene||{},fallback=resolved.resolved||{};const resolvedValue=(key,label)=>fallback[key]&&!wardrobe.locked?`${label}: ${promptList(fallback[key])}`:'';const lines=[`Create a photoreal editorial portrait of ${c.name}, a ${c.identity.age}-year-old ${c.identity.occupation} based in ${c.identity.location}.`,`Subject: ${promptList(appearance.facialStructure)} face; ${promptList(appearance.facialFeatures)}; ${promptList(appearance.skinDetails)}; ${appearance.hair?.colour||''} ${appearance.hair?.style||''} hair; ${promptList(appearance.signatureFeatures)}.`,`Presence: ${promptList(c.personality?.traits)}; ${expression.pose||'relaxed stance'}; ${expression.expression||'natural expression'}.`,`Wardrobe: ${promptList(wardrobe.items)||resolvedValue('wardrobe','Wardrobe')||'coherent contemporary clothing'}.`,`Scene: ${scene.name||scene.location||resolvedValue('locations','Setting')||'an editorial setting'}${scene.location?` — ${scene.location}`:''}${scene.activity?`; activity: ${scene.activity}`:''}.`,`Photography: ${photo.shotType||'editorial portrait'}, ${photo.lens||'50mm'} lens, ${photo.angle||'eye-level'} angle.`,`Lighting: ${lighting.behaviour||'natural'} light with ${lighting.colourTreatment||'neutral'} colour treatment.`,resolvedValue('accessories','Accessories'),resolvedValue('grooming','Grooming'),resolvedValue('props','Props'),`Preserve canonical identity, facial structure, hair colour, and defining features. Avoid text, watermarks, distorted hands, duplicate limbs, or unrelated wardrobe substitutions.`].filter(Boolean);return lines.join('\n')}});
export function compilePrompt(state,compiler=MockCompiler,options={}){const source=resolveStudioState(state,options);const prompt={id:`prompt_${Date.now()}`,characterId:state.character.id,createdAt:new Date().toISOString(),compiler:{provider:options.provider||'mock',model:options.model||'studio-baseline',profile:options.profile||'photoreal-director'},sourceState:source,text:compiler.compile(source,options),edited:false};return {...state,compiledPrompts:[prompt,...state.compiledPrompts],resolvedDirectorState:source,dirty:false,lastPrompt:prompt}}
export function compileGeneration(state,compiler=MockCompiler,options={}){const originalLocks=state.resolverLocks||{};const hasWardrobe=state.resolvedDirectorState?.resolved?.wardrobe!==undefined;const preserveWardrobe=state.generationOptions?.newWardrobe===false&&hasWardrobe;const resolvingState=preserveWardrobe?{...state,resolverLocks:{...originalLocks,wardrobe:true}}:state;const compiled=compilePrompt(resolvingState,compiler,options);return preserveWardrobe?{...compiled,resolverLocks:originalLocks}:compiled}
export function createTake(state,variationReason='new-take',image=null){if(!state.character)throw new Error('Character Core required before creating a Take');const presets=[{shotType:'Editorial portrait',lens:'85mm',angle:'Three-quarter',pose:'Three-quarter stance',expression:'Assured gaze'},{shotType:'Candid',lens:'35mm',angle:'Eye level',pose:'Mid-step',expression:'Unscripted smile'},{shotType:'Full body',lens:'50mm',angle:'Low angle',pose:'Grounded stance',expression:'Focused calm'},{shotType:'Close-up',lens:'105mm',angle:'Eye level',pose:'Shoulders turned',expression:'Quiet intensity'}];const preset=presets[state.takes.length%presets.length];const photography=state.visualSettings.photography.locked?state.visualSettings.photography:{...state.visualSettings.photography,shotType:preset.shotType,lens:preset.lens,angle:preset.angle};const expression=state.generationOptions.newPose?{pose:preset.pose,expression:preset.expression}:state.visualSettings.expression;const variedState={...state,generationOptions:{...state.generationOptions,seed:`promptforge-take-${state.takes.length+1}`},visualSettings:{...state.visualSettings,expression,photography}};const snapshot={...variedState,takes:[],compiledPrompts:[]};delete snapshot.lastPrompt;const take=withTakeSemantics({id:`take_${Date.now()}_${state.takes.length+1}`,createdAt:new Date().toISOString(),image,characterId:state.character.id,characterRevision:state.character.revision,stateSnapshot:clone(snapshot),compiledPromptId:state.lastPrompt?.id||null,parentTakeId:state.selectedTake||null,variationReason:`${variationReason}: ${photography.shotType} · ${photography.lens}`});return {...variedState,takes:[...state.takes,take],selectedTake:take.id,dirty:false}}
export function promoteTake(state,takeId){if(!state.takes.some(t=>t.id===takeId))return state;return {...state,selectedTake:takeId,dirty:false}}
